function resolveExploreHost() {
  try {
    const b = globalThis.$?.('body')?.[0];
    if (b?.ownerDocument?.defaultView) return b.ownerDocument.defaultView;
  } catch (_) {}
  try {
    if (globalThis.window?.parent?.document?.body) return globalThis.window.parent;
  } catch (_) {}
  return globalThis.window || globalThis;
}

